mapper.select:
SELECT line.*, price_head.FIX_PRICE_NO, price.VENDOR_ID vendorId,price.VENDOR_CODE vendorCode,price.VENDOR_NAME vendorName,price.CURRENCY_CODE currencyName, price.NOTAX_PRICE unitPrice,price.TAX_RATE taxRate, price.INVOICE_TYPE, price.ORDER_REMARK, price.EXT_WARRANTY_PERIOD warrantyPeriod,price.EXT_LEAD_TIME leadTime,price.PAYMENT_TERM,price.PAYMENT_METHOD FROM meicloud_usrm_cloud_biz_supplier_cooperate.scc_pr_requirement_line line JOIN meicloud_usrm_cloud_biz_sou.scc_npm_sou_fix_price_line price ON price.REQUIREMENT_LINE_IDS LIKE(CONCAT('%', line.requirement_line_id ,'%')) JOIN meicloud_usrm_cloud_biz_sou.scc_npm_sou_fix_price_head price_head ON price_head.FIX_PRICE_HEAD_ID = price.FIX_PRICE_HEAD_ID WHERE price_head.FIX_PRICE_STATUS = 'APPROVED' AND line.EXT_POOL_STATUS = 'Y' AND line.EXT_BUY_TYPE IN('RECENT_PURCHASE','NONE_PRICE') AND line.ORDER_QUANTITY > 0 AND line.CEEA_PERFORM_USER_ID IS NOT NULL
and line.REQUIREMENT_LINE_ID in
#{item}
AND line.REQUIREMENT_HEAD_NUM like CONCAT('%',#{params.requirementHeadNum},'%')
AND line.MATERIAL_CODE like CONCAT('%',#{params.materialCode},'%')
AND line.EXT_USE_DEPARTMENT_NAME like CONCAT('%',#{params.extUseDepartmentName},'%')
AND line.ORG_ID = #{params.orgId}
AND line.ORG_ID in
#{item}
AND line.CEEA_PERFORM_USER_ID = #{params.ceeaPerformUserId}
AND line.MATERIAL_NAME like CONCAT('%',#{params.materialName},'%')
AND price.VENDOR_NAME like CONCAT('%',#{params.vendorName},'%')
ORDER BY line.REQUIREMENT_LINE_ID DESC
